import json

def parse_json(s):
    try:
        return json.loads(s)
    except json.JSONDecodeError as e:
        print(f'Invalid JSON: {e}')
        return None

result_a = parse_json('{"x": 1}')
result_b = parse_json('{"y": 2}')
result_c = parse_json('{"z": 3}')

import json

def filter_expensive_products(json_str):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return []
    result = []
    for item in data:
        if isinstance(item, dict) and isinstance(item.get('price'), (int, float)):
            if item['price'] >= 50.0:
                result.append(item['name'])
    return result

products = '[{"name": "Laptop", "price": 800}, {"name": "Pen", "price": 2.5}, {"name": "Tablet", "price": 55}]'
print(filter_expensive_products(products))

