import json

sales_json = '[{"date": "2024-01-01", "product": "Millet", "revenue": 120}, {"date": "2024-01-01", "product": "Millet", "revenue": 80}, {"date": "2024-01-02", "product": "Sorghum", "revenue": 150}]'

def aggregate_revenue(json_str):
    try:
        records = json.loads(json_str)
    except json.JSONDecodeError:
        return {}
    summary = {}
    for record in records:
        product = record.get('product')
        revenue = record.get('revenue', 0)
        if product is not None:
            summary[product] = summary.get(product, 0) + revenue
    return summary

print(aggregate_revenue(sales_json))

import json

nested = '{"level1": {"name": "Alpha", "value": 42}, "level2": [{"label": "Beta"}, "Gamma", 99]}'

def collect_strings(data):
    result = []
    if isinstance(data, dict):
        for value in data.values():
            result.extend(collect_strings(value))
    elif isinstance(data, list):
        for item in data:
            result.extend(collect_strings(item))
    elif isinstance(data, str):
        result.append(data)
    return result

parsed = json.loads(nested)
result = collect_strings(parsed)
print(result)
